mobile_http_calls.call_arguments:
ApiEndpoints.alerts,
queryParameters: {
  // The real filter is `state` (open/resolved) — `resolved` was
  // silently ignored by the backend, so this used to also return
  // resolved alerts mixed into the "active" list.
  'filter[state]': 'open',
  'limit': 50,
  if (cursor != null) 'cursor': cursor,
},

ApiEndpoints.products,
queryParameters: {
  if (search != null && search.trim().isNotEmpty)
    'search': search.trim(),
  'limit': 100,
},

ApiEndpoints.nonConformities,
data: {
  'subject_type': subjectType,
  'subject_id': subjectId,
  'description': description,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.devicePrograms(deviceId),
data: {
  'name': name,
  'target_temperature_celsius': temperatureCelsius,
  'plateau_minutes': plateauMinutes,
  'is_active': isActive,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.deviceProgram(deviceId, programId),
data: {
  if (name != null) 'name': name,
  if (temperatureCelsius != null)
    'target_temperature_celsius': temperatureCelsius,
  if (plateauMinutes != null) 'plateau_minutes': plateauMinutes,
  if (isActive != null) 'is_active': isActive,
},

'/v1/devices',
data: {
  'site_id': siteId,
  'name': name,
  'serial_number': serialNumber,
  'kind': kind,
  'status': 'active',
  if (manufacturer != null) 'manufacturer': manufacturer,
  if (model != null) 'model': model,
  if (notes != null) 'notes': notes,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.device(id),
data: {
  if (name != null) 'name': name,
  if (model != null) 'model': model,
  if (serialNumber != null) 'serial_number': serialNumber,
  if (manufacturer != null) 'manufacturer': manufacturer,
  if (status != null) 'status': status,
  if (notes != null) 'notes': notes,
},

ApiEndpoints.deviceMaintenanceRecords(deviceId),
data: {
  'kind': kind,
  if (technician != null && technician.isNotEmpty)
    'technician': technician,
  'performed_at': performedAt.toIso8601String(),
  if (nextDueAt != null) 'next_due_at': nextDueAt.toIso8601String(),
  if (description != null && description.isNotEmpty)
    'description': description,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.dluRules,
data: {
  'packaging_type': packagingType,
  'storage_condition': storageCondition,
  'shelf_life_days': shelfLifeDays,
  'reason': reason,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.auditEvents,
queryParameters: {
  if (cursor != null) 'cursor': cursor,
  if (action != null && action.isNotEmpty) 'filter[action]': action,
  if (actorId != null && actorId.isNotEmpty)
    'filter[actor_id]': actorId,
  if (subjectType != null && subjectType.isNotEmpty)
    'filter[subject_type]': subjectType,
  if (from != null) 'filter[from]': from.toIso8601String(),
  if (to != null) 'filter[to]': to.toIso8601String(),
  'limit': 30,
},

ApiEndpoints.labelUsage(labelId),
data: payload,
options: Options(
  headers: {
    'Idempotency-Key': idempotencyKey ?? generateIdempotencyKey(),
  },
),

ApiEndpoints.prostheticCases, queryParameters: {
        if (cursor != null) 'cursor': cursor,
        if (patientReference != null && patientReference.isNotEmpty)
          'patient_reference': patientReference,
        if (practitionerId != null) 'practitioner_id': practitionerId,
        if (laboratoryId != null) 'laboratory_id': laboratoryId,
        if (workType != null) 'work_type': workType,
        if (status != null) 'status': status,
        if (from != null) 'from': from,
        if (to != null) 'to': to,
        'limit': 20,
      }

ApiEndpoints.evidenceSearch,
queryParameters: {
  if (cursor != null) 'cursor': cursor,
  if (patientReference != null && patientReference.isNotEmpty)
    'patient_reference': patientReference,
  if (cycleNumber != null) 'cycle_number': cycleNumber,
  if (batchNumber != null && batchNumber.isNotEmpty)
    'batch_number': batchNumber,
  if (from != null) 'from': from.toIso8601String(),
  if (to != null) 'to': to.toIso8601String(),
  'limit': 20,
},

ApiEndpoints.stockLevels,
queryParameters: {
  if (search != null && search.trim().isNotEmpty)
    'search': search.trim(),
  'limit': 100,
},

ApiEndpoints.stockTransfer,
data: {
  'batch_id': batchId,
  'from_location_id': fromLocationId,
  'to_location_id': toLocationId,
  'qty': qty,
  if (reason != null && reason.trim().isNotEmpty)
    'reason': reason.trim(),
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.suppliers,
data: {
  'name': name,
  if (email != null) 'email': email,
  if (phone != null) 'phone': phone,
  if (address != null) 'address': address,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),

ApiEndpoints.supplierProducts(supplierId),
data: {
  'product_id': productId,
  if (supplierReference != null)
    'supplier_reference': supplierReference,
  if (packSize != null) 'pack_size': packSize,
  if (price != null) 'price': price,
},
options: Options(
  headers: {'Idempotency-Key': generateIdempotencyKey()},
),
